import { SUPPORT_LESSON_TEXT } from './support';
import { withDistractors } from './distractors';
import type { Session, CheckItem } from './types';
import { enrich } from './enrich';
import { phaseForWeek } from './phases';
import { EXAMPLES } from './examples';
import { EXTRA_TEACH } from './extra';
import { TOPICS } from './topics';

type C = [string, string[], number, string];
const mk = (week: number, day: number, kind: Session['kind'], title: string, objective: string,
  teach: string[], practice: string[], checks: C[], reflect: string, claimIds: string[]): Session => {
  const id = `w${String(week).padStart(2, '0')}d${day}`;
  const tb = TOPICS[id];
  if (tb) { teach = [...teach, ...tb.teach]; checks = [...checks, tb.check]; }
  return enrich({
    id, week, day, phase: phaseForWeek(week).id, title, objective, kind,
    minutes: kind === 'checkpoint' ? 12 : 8, teach: EXTRA_TEACH[id] ? [...teach, EXTRA_TEACH[id]] : teach, example: EXAMPLES[id], practice, reflect, claimIds,
    checks: checks.map(([q, options, answer, why], i): CheckItem => ({ id: `${id}-q${i + 1}`, q, options, answer, why })),
  });
};

const RAW: Session[] = [
// WEEK 1 Foundations
mk(1,1,'lesson','What emotions are for','Describe emotions as signals that prepare action, not as commands.',
 ['An emotion is a whole-body response to something that matters to you. It usually includes a situation, an interpretation of that situation, bodily changes, an urge to act, and a feeling you can name.',
  'Emotions carry information. Anger often signals a perceived obstacle or unfairness. Anxiety signals a possible threat. Sadness signals loss. The signal can be accurate or mistaken, and it is still worth reading.',
  'Feeling an emotion and acting on it are two different events. This whole programme trains the space between them.'],
 ['Recall one moment from the last 24 hours when you felt something clearly.','Name the situation in one sentence of plain fact.','Name the emotion and the urge it came with.'],
 [['Which statement best fits how this programme treats emotions?',['Emotions should be removed','Emotions are signals; actions are choices','Emotions are always accurate','Strong emotions mean weakness'],1,'Emotions are information. The training targets the choice of response, not the removal of feeling.'],
  ['Anxiety most typically signals...',['A loss that has happened','A possible threat ahead','An unfair obstacle','Nothing useful'],1,'Anxiety is future-oriented: it prepares you for a possible threat.']],
 'What emotion do you notice most often in your week, and what does it usually try to get you to do?',['gross1998-c1']),
mk(1,2,'lesson','The emotion chain','Map an episode as situation, interpretation, body, urge, action, outcome.',
 ['An emotional episode unfolds as a chain: a situation happens, you interpret it, your body reacts, an urge appears, you act (or not), and there is an outcome.',
  'The process model of emotion regulation shows that you can step in at several points: choosing or changing the situation, shifting attention, changing the interpretation, or changing the response.',
  'Earlier steps are often easier to influence than later ones. Once the urge is strong, you have fewer options, so the training builds skills at each link.'],
 ['Take yesterday\'s moment from Session 1.','Write the six links: situation, interpretation, body, urge, action, outcome.','Mark one link where a different choice was possible.'],
 [['In the process model, changing how you interpret a situation is called...',['Situation selection','Cognitive change','Response modulation','Attentional deployment'],1,'Reinterpreting meaning is cognitive change, also called reappraisal.'],
  ['Why practise at early links in the chain?',['They feel nicer','There are usually more options before the urge peaks','Later links do not matter','It avoids all emotion'],1,'Earlier steps leave more room for choice.']],
 'Where in the chain do you usually notice yourself, early or late?',['gross1998-c1']),
mk(1,3,'lesson','Regulation is not suppression','Contrast suppressing expression with flexible regulation.',
 ['Suppression means hiding the outward signs of an emotion while still feeling it. Correlational research links habitual suppression with worse wellbeing and relationships than habitual reappraisal.',
  'This does not mean you should express everything. A surgeon or a negotiator may need to hold a neutral face for a while. The skill is choosing on purpose and not relying on one strategy everywhere.',
  'The goal of this lab is flexible regulation: notice the emotion, allow it, and pick a response that fits the context and your goals.'],
 ['Think of a recent time you hid a feeling.','Was hiding it useful in that moment? What did it cost later?','Write one alternative you could have used alongside or instead.'],
 [['What does the research summarised here suggest about habitual suppression?',['It is linked to better wellbeing','It is linked to worse wellbeing and relationships than reappraisal','It has no associations','It is always harmful in every moment'],1,'The finding is correlational and about habits, not about every single use.'],
  ['The aim of this programme is...',['Never showing emotion','Flexible, context-sensitive regulation','Expressing everything','Avoiding difficult situations'],1,'Flexibility across contexts is the target.']],
 'When is hiding a feeling genuinely useful for you, and when does it backfire?',['grossjohn2003-c1','bonanno2013-c1']),
mk(1,4,'practice','How you will learn here','Use retrieval and spacing to make skills stick.',
 ['Reading about a skill is not the same as being able to use it under pressure. This lab uses retrieval practice (answering from memory) and spaced reviews (returning after days) because both improve long-term retention in learning research.',
  'Each lesson has quick checks. Each phase ends with a checkpoint. Items you master come back later as reviews. Completion, mastery and retention are tracked separately, so finishing a lesson is never counted as knowing it.',
  'Getting a question wrong is useful: it tells the system what to bring back.'],
 ['Without looking back, write the six links of the emotion chain.','Check against Session 2.','Note which link you forgot.'],
 [['Which learning technique does this lab rely on?',['Rereading notes','Retrieval and spaced practice','Highlighting','Listening only'],1,'Practice testing and distributed practice are rated high-utility techniques.'],
  ['Is finishing a lesson counted as mastery here?',['Yes','No, mastery requires a checkpoint score','Only on weekends','Only for scenarios'],1,'Completion, mastery and retention are separate measures.']],
 'What makes it hard for you to practise something regularly, and what small change would help?',['roediger2006-c1','cepeda2006-c1','dunlosky2013-c1']),
mk(1,5,'checkpoint','Week 1 checkpoint','Demonstrate the foundations.',
 ['This checkpoint mixes questions from the week. Answer from memory. A score of 80% or more marks the phase as mastered. The 80% threshold is a design choice for this app, not a research-derived cut-off.'],
 ['Answer the checkpoint questions.','Read each explanation, even for correct answers.'],
 [['An urge to shout is best described as...',['An action already taken','A readiness to act that can be noticed','The situation','A fact'],1,'Urges precede actions and can be observed.'],
  ['Which is a plain fact rather than an interpretation?',['She ignored me on purpose','She did not reply to my message today','She does not respect me','She is always rude'],1,'Facts are observable and free of motive guesses.'],
  ['Flexible regulation means...',['Always reappraising','Choosing strategies that fit context and goals','Never feeling anger','Always expressing feelings'],1,'No single strategy fits everywhere.']],
 'What is one idea from this week you want to remember?',['gross1998-c1','bonanno2013-c1']),
// WEEK 2 Noticing and naming
mk(2,1,'lesson','Emotion granularity','Use precise emotion words instead of "bad" or "stressed".',
 ['People differ in how finely they distinguish their emotions. Saying "irritated, embarrassed and worried" carries more information than "bad".',
  'Studies link finer emotion differentiation with using more regulation strategies under strong emotion and with better coping, though the causal direction is not settled.',
  'Precision helps you choose: embarrassment calls for a different response than irritation.'],
 ['Pick a recent "stressed" moment.','Replace "stressed" with two or three more specific words.','Rate each word 0 to 10 for intensity.'],
 [['Which label is most granular?',['Bad','Upset','Disappointed and a little embarrassed','Not good'],2,'Specific, combined labels carry the most information.'],
  ['What does research say about granularity?',['It is proven to cause wellbeing','It is associated with better coping; causality is not settled','It is harmful','It cannot be learned'],1,'Keep claims at the level the evidence supports.']],
 'Which emotion words do you rarely use but might actually be feeling?',['barrett2001-c1','kashdan2015-c1']),
mk(2,2,'lesson','Affect labelling','Name feelings in words to create a small pause.',
 ['Putting a feeling into words, such as "this is frustration", is called affect labelling. A neuroimaging study found labelling was associated with lower amygdala response to emotional images.',
  'In daily life the practical value is a brief pause and a shift from being inside the feeling to observing it. It is not a cure; it is a first step.',
  'Use a neutral form: "I notice frustration" rather than "I am a frustrated person".'],
 ['Next time a feeling rises today, say silently: "I notice ___".','Add intensity: "about a 6".','Note what happened in the next 10 seconds.'],
 [['"I notice anxiety, about a 5" is an example of...',['Suppression','Affect labelling','Distraction','Venting'],1,'Naming the feeling in words is affect labelling.'],
  ['Which wording keeps more distance?',['I am an angry person','I notice anger','Anger is ruining me','Everyone makes me angry'],1,'"I notice" frames the feeling as an observable state.']],
 'What happened when you named a feeling today?',['lieberman2007-c1']),
mk(2,3,'lesson','Mixed and layered emotions','Recognise that several emotions can co-occur or hide one another.',
 ['Emotions often come in layers. Anger can sit on top of hurt. Irritation can cover anxiety about failing.',
  'The first emotion you notice is not always the most important one. Asking "what else is here?" often reveals the feeling that best explains your urge.',
  'This is an exploratory question, not a diagnosis. Treat the answer as a working hypothesis.'],
 ['Recall a time you were angry.','Ask: what else was here? Hurt, fear, shame, disappointment?','Write which layer best explains what you wanted at the time.'],
 [['Anger covering hurt is an example of...',['A single emotion','Layered emotions','Suppression','A fact'],1,'More than one emotion can be present at once.'],
  ['The answer to "what else is here?" should be treated as...',['A certain diagnosis','A working hypothesis','Irrelevant','A fact about your personality'],1,'Stay tentative about inner causes.']],
 'Which emotion tends to show up as a cover for another in your life?',['barrett2001-c1']),
mk(2,4,'practice','Daily check-in habit','Build a 30-second check-in.',
 ['A short daily check-in builds the noticing habit. It should take under a minute so you keep doing it.',
  'Use the Journal\'s quick check-in: pick up to three emotions, rate intensity, add one optional line. You do not need to write essays.',
  'Patterns become visible after a couple of weeks, not after a day.'],
 ['Open the Journal and add a quick check-in now.','Choose one fixed moment in your day (after lunch, end of work) for tomorrow\'s check-in.'],
 [['How long should the daily check-in take?',['About 30 to 60 seconds','20 minutes','An hour','It should be skipped'],0,'Short practices are more sustainable.'],
  ['When do patterns become visible?',['After one entry','After repeated entries over weeks','Never','Only with notifications'],1,'Patterns need data over time.']],
 'What cue in your day could anchor the check-in?',['gollwitzer2006-c1']),
mk(2,5,'checkpoint','Week 2 checkpoint','Demonstrate precise noticing and naming.',
 ['Mixed questions from the week. 80% or more marks this phase mastered (design choice).'],
 ['Answer from memory.','Review explanations.'],
 [['Which is the best replacement for "I feel stressed" before a presentation?',['I feel bad','I feel nervous and a bit excited','I feel nothing','I feel weird'],1,'Granular and possibly mixed.'],
  ['Affect labelling works best phrased as...',['I am hopeless','I notice sadness','Sadness is wrong','Stop feeling'],1,'Observing language.'],
  ['When anger covers hurt, which question helps?',['Who is to blame?','What else is here?','How do I stop feeling?','Why am I like this?'],1,'Exploring layers.']],
 'Which naming habit will you keep?',['barrett2001-c1','lieberman2007-c1']),
// WEEK 3 Body and impulse
mk(3,1,'lesson','Body signals','Locate emotion in the body without judging it.',
 ['Emotions show up in the body: tight jaw, warm face, fast heartbeat, heavy chest, restless legs. These sensations are often the earliest signal available.',
  'Body signals are not reliable labels on their own. A fast heartbeat can be anxiety, excitement or coffee. Use them as an early alert, then name the emotion.',
  'A body scan of 30 seconds, top to bottom, is enough.'],
 ['Do a 30-second scan now: head, jaw, shoulders, chest, stomach, hands.','Note any tension or heat.','Name one possible emotion that fits, if any.'],
 [['Why are body signals useful?',['They are always accurate labels','They can be an early alert','They replace naming','They prove the situation is dangerous'],1,'They arrive early but need interpretation.'],
  ['A fast heartbeat could reflect...',['Only anxiety','Anxiety, excitement or caffeine','Only anger','Nothing'],1,'Same sensation, different causes.']],
 'Where does your body first show stress?',['gross1998-c1']),
mk(3,2,'lesson','Urge is not action','Notice an urge and delay acting on it.',
 ['Every emotion carries an action tendency: anger pushes to attack or defend, anxiety to avoid, shame to hide.',
  'Noticing "I have the urge to send a sharp reply" creates a gap. You do not have to fight the urge; you only need to not act yet.',
  'A simple rule: for any message written in strong emotion, wait and reread before sending.'],
 ['Name your three most common urges under stress.','For each, write a delay action: wait 10 minutes, draft but do not send, take a walk.'],
 [['An action tendency is...',['The action itself','A readiness to act in a certain way','A fact','A memory'],1,'Tendency, not behaviour.'],
  ['Best first move with an urge to fire off an angry email?',['Send it quickly','Notice the urge and delay sending','Delete your account','Suppress all feeling'],1,'Delay protects choice.']],
 'Which urge costs you the most when you act on it?',['gross1998-c1']),
mk(3,3,'lesson','Why venting does not drain anger','Replace venting with lower-arousal responses.',
 ['A popular idea says anger builds like steam and must be let out. An experiment found that hitting a punching bag while thinking about the person who angered you did not reduce anger and was followed by more aggression than doing nothing.',
  'Lower-arousal options such as slow breathing, a walk with a neutral focus, or a distraction task give the urge time to fall.',
  'Talking to someone can still help when it aims at understanding or problem solving rather than replaying the grievance.'],
 ['Plan one lower-arousal action for your next angry moment.','Write it as: "If I feel angry at work, then I will step out and walk for five minutes."'],
 [['What did the venting experiment find?',['Venting reduced anger','Venting did not reduce anger and was followed by more aggression','No effect of any kind','Venting is required'],1,'Rumination-based venting kept anger going.'],
  ['Talking it over helps most when it focuses on...',['Replaying the grievance','Understanding or solving','Insulting the person','Proving you are right'],1,'Purpose matters.']],
 'What do you usually do with anger, and does it lower it?',['bushman2002-c1']),
mk(3,4,'practice','Slow breathing and grounding','Use a short physiological reset.',
 ['Slow breathing with a longer out-breath is a simple way to lower arousal for many people. Try about four seconds in and six seconds out for one minute.',
  'Grounding redirects attention to the present: name five things you see, four you can touch, three you hear.',
  'These are response-modulation and attention tools. They do not solve the situation; they make you ready to choose.'],
 ['Do one minute of 4-in, 6-out breathing now (timer in the practice panel).','Rate your tension before and after, 0 to 10.'],
 [['In the process model, slow breathing mainly acts on...',['Situation selection','Response modulation','Cognitive change','Nothing'],1,'It changes the physiological response.'],
  ['Do grounding tools solve the problem?',['Yes, completely','No, they help you get ready to choose','They make it worse','Only at night'],1,'They are preparation, not resolution.']],
 'Which reset will you actually use in public?',['gross1998-c1']),
mk(3,5,'checkpoint','Week 3 checkpoint','Demonstrate body and impulse skills.',
 ['Mixed questions. 80% or more marks mastery (design choice).'],['Answer from memory.'],
 [['First step when you notice a hot face in a meeting?',['Leave immediately','Notice it as an early signal and name the emotion','Argue harder','Ignore all signals'],1,'Early alert, then name.'],
  ['Which is least likely to reduce anger?',['Slow breathing','Walking with a neutral focus','Replaying the insult while hitting something','Waiting before replying'],2,'Rehearsal maintains anger.'],
  ['An urge is best handled by...',['Acting quickly','Noticing and delaying action','Shame','Hiding forever'],1,'Delay creates choice.']],
 'What did you learn about your own body signals?',['bushman2002-c1']),
// WEEK 4 Interpretations I
mk(4,1,'lesson','Facts versus interpretations','Separate what happened from what you made it mean.',
 ['A fact is what a camera would record: words said, actions taken, times. An interpretation is the meaning you add: motives, judgements, predictions.',
  'Interpretations are not wrong by default, but they are guesses. Emotions often respond to the interpretation more than the fact.',
  'Writing the two side by side is one of the most useful skills in this lab.'],
 ['Take a recent irritation.','Write two columns: "camera facts" and "my interpretation".','Count how many items in the fact column contain a motive. Move them.'],
 [['Which is a camera fact?',['He was dismissive','He looked at his phone while I spoke','He does not care','He thinks I am stupid'],1,'Observable behaviour only.'],
  ['Emotions often respond most strongly to...',['Facts alone','Our interpretation of facts','Weather','Nothing'],1,'Appraisal drives emotion.']],
 'Which interpretation do you make most automatically?',['gross1998-c1']),
mk(4,2,'lesson','Generating alternatives','Produce at least three plausible readings.',
 ['When one interpretation feels obviously true, generate at least two alternatives. Not to talk yourself out of the feeling, but to test how certain you really are.',
  'Example: a colleague did not reply. Possible readings: busy, did not see it, annoyed with me, waiting for information. Which has the most evidence?',
  'This is the core move of reappraisal: changing the meaning when the first meaning is not well supported.'],
 ['Write three alternative explanations for a recent event.','Rate each 0 to 100% for likelihood.','Notice whether your emotion shifts.'],
 [['The purpose of generating alternatives is...',['To prove you were wrong','To test how certain your first reading is','To ignore feelings','To blame others'],1,'It tests certainty.'],
  ['Changing meaning to change emotion is called...',['Suppression','Reappraisal','Venting','Avoidance'],1,'Cognitive change, reappraisal.']],
 'When was your first interpretation wrong recently?',['webb2012-c1','ochsner2005-c1']),
mk(4,3,'lesson','Common thinking traps','Spot mind-reading, catastrophising and all-or-nothing thinking.',
 ['Some interpretation habits are common under stress: mind-reading (assuming you know what others think), catastrophising (jumping to the worst outcome), all-or-nothing (one mistake equals total failure), and personalising (assuming it is about you).',
  'Spotting a trap does not make the thought false. It flags that the thought deserves a check.',
  'Label it lightly: "that might be mind-reading".'],
 ['Read your last three worries.','Tag any that fit a trap.','Write one balanced version for each tagged worry.'],
 [['"They all think I am incompetent" without evidence is...',['A fact','Mind-reading','Problem solving','Granularity'],1,'Assuming others\' thoughts.'],
  ['Spotting a trap means the thought is...',['Definitely false','Worth checking','Definitely true','Irrelevant'],1,'Flag, then check.']],
 'Which trap is your most frequent visitor?',['webb2012-c1']),
mk(4,4,'practice','Evidence check','Weigh evidence for and against an interpretation.',
 ['Take one interpretation and ask: what supports it, what does not, what would I tell a friend, and what is the most useful way to see this that still fits the facts?',
  'Useful does not mean positive. "This is a real problem and I can take one step on it" is often better than false reassurance.',
  'Reappraisal research shows benefits on average, but effects vary by tactic and context.'],
 ['Pick a current concern.','Answer the four questions in the Journal reflection.','Write one balanced statement.'],
 [['A good reappraisal must be...',['Always positive','Fitting the facts and useful','Unrealistic','Avoidant'],1,'Accurate and useful.'],
  ['What would I tell a friend? helps by...',['Adding distance and fairness','Proving superiority','Avoiding the issue','Increasing blame'],0,'It borrows an outside view.']],
 'What is one balanced statement you can keep for this week?',['webb2012-c1']),
mk(4,5,'review','Week 4 review','Retrieve interpretation skills.',
 ['Review week. Answer from memory; items you miss will return.'],['Answer the questions.','Revisit any lesson you found shaky.'],
 [['Which is an interpretation?',['The meeting ran 20 minutes over','The manager is out to get me','The email arrived at 9pm','She said "we need to talk"'],1,'Motive guess.'],
  ['Catastrophising is...',['Precise labelling','Jumping to the worst outcome','Slow breathing','Problem solving'],1,'Worst-case leap.']],
 'Which skill from this week was hardest?',['webb2012-c1']),
// WEEK 5 Interpretations II
mk(5,1,'lesson','Self-distancing','View an event from a step back.',
 ['Reflecting on a difficult event as if watching from a distance, or using your own name ("Why is Wangden upset?"), is linked with less reactivity and less rumination than replaying it from inside.',
  'Distance helps you ask "why" questions without sinking back into the feeling.',
  'Try a fly-on-the-wall view: what would an observer see?'],
 ['Recall a difficult moment.','Describe it in third person in three sentences.','Note one thing you see now that you missed.'],
 [['Self-distancing involves...',['Reliving vividly','Viewing from an observer stance','Suppressing','Ignoring the event'],1,'Observer perspective.'],
  ['Compared with self-immersion, distancing was associated with...',['More rumination','Less reactivity and rumination','No difference','Anger'],1,'Per the cited research.']],
 'How did the third-person view change the story?',['krossayduk2011-c1']),
mk(5,2,'lesson','Temporal distance','Ask how this will matter in a week, a year.',
 ['Distance in time changes proportion: most everyday setbacks shrink when you picture them from next week or next year, while the things that still matter stand out more clearly.',
  'Distance has limits. It works less well for ongoing problems, such as a manager who belittles you every week, because the pattern itself will still matter in a year. There, use the future view to decide what to change rather than to make the feeling smaller.'],
 ['Write: In one week I will think...; In one year I will think...','Write one action future-you would thank you for.'],
 [['Temporal distancing asks...',['How will this look later?','Who is to blame?','How to suppress?','What is wrong with me?'],0,'Time perspective.'],
  ['If an event will still matter in a year, the next step is...',['Pretend otherwise','Plan a useful action','Ruminate','Give up'],1,'Matter plus action.']],
 'What does future-you want you to do about a current concern?',['krossayduk2011-c1']),
mk(5,3,'lesson','Acceptance and willingness','Allow a feeling while acting on what matters.',
 ['Sometimes the facts are clear and painful and no reinterpretation fits. Acceptance means making room for the feeling instead of fighting it, while still choosing actions that fit your values.',
  'Approaches such as Acceptance and Commitment Therapy target acceptance and values-based action; evidence is supportive but varied.',
  'A phrase: "This is hard, and I can still do the next useful thing."'],
 ['Name a feeling you have been fighting.','Say: "I can let this be here for a moment."','Name one small action you value that you can do anyway.'],
 [['Acceptance in this sense means...',['Approving of the situation','Allowing the feeling while choosing action','Giving up','Suppressing'],1,'Allowing, not approving.'],
  ['When no reinterpretation fits the facts...',['Lie to yourself','Acceptance plus valued action can help','Ruminate','Vent'],1,'Use a different tool.']],
 'What value do you want to act on even when uncomfortable?',['hayes2006-c1','kashdan2010-c1']),
mk(5,4,'practice','Reappraisal drills','Practise fast, fair reappraisals.',
 ['Speed comes from repetition. In this drill you read short situations and write a fair alternative reading in under a minute.',
  'Watch for "positive spin" that does not fit the facts; that tends not to stick.',
  'The Scenario Gym has longer versions of this drill.'],
 ['Situation: your proposal was turned down in two lines. Write an alternative reading.','Situation: a friend cancelled late. Write an alternative reading.','Rate how believable each is.'],
 [['A believable reappraisal of a rejected proposal is...',['They hate me','The timing or budget may not fit; I can ask for feedback','It was perfect and they are fools','I will never succeed'],1,'Fits facts and suggests action.'],
  ['Positive spin that does not fit the facts tends to...',['Stick well','Not be believed','Always help','Be required'],1,'Believability matters.']],
 'Which drill felt most natural?',['webb2012-c1']),
mk(5,5,'checkpoint','Interpretations checkpoint','Demonstrate interpretation skills (weeks 4-5).',
 ['Phase checkpoint for weeks 4 and 5. 80% or more marks mastery (design choice).'],['Answer from memory.'],
 [['"She must think I am lazy" is an example of...',['Fact','Mind-reading','Acceptance','Grounding'],1,'Assumed thoughts.'],
  ['Which helps when a painful fact cannot be reinterpreted?',['Acceptance with valued action','Positive spin','Venting','Suppression'],0,'Acceptance fits.'],
  ['Using your own name to reflect is a form of...',['Self-distancing','Suppression','Rumination','Catastrophising'],0,'Distanced self-talk.']],
 'Which interpretation skill will you use first next time?',['krossayduk2011-c1','webb2012-c1']),
// WEEK 6 Strategy choice
mk(6,1,'lesson','A toolkit, not a rule','Know the main strategy families.',
 ['Main families: change the situation (choose or modify it), shift attention (distraction, focus), change the meaning (reappraisal, distancing), accept (allow the feeling), and change the response (breathing, delaying action).',
  'Regulatory flexibility research suggests that adaptiveness comes from reading the context, having several options and adjusting based on feedback.',
  'Ranking strategies as good or bad in all cases is not supported.'],
 ['List one strategy you already use from each family.','Mark the family you rarely use.'],
 [['Regulatory flexibility includes...',['One best strategy','Context sensitivity, repertoire, feedback','Never adjusting','Avoiding all feelings'],1,'Three components.'],
  ['Asking a colleague to move a meeting is...',['Situation modification','Suppression','Reappraisal','Rumination'],0,'Changing the situation.']],
 'Which family is missing from your toolkit?',['bonanno2013-c1','gross_future2013-c1']),
mk(6,2,'lesson','Intensity matters','Match strategy to intensity.',
 ['Distraction is useful short-term and becomes a problem if it turns into avoiding things that need attention.',
  'Rate intensity with a quick 0 to 10 check. You do not need precision: "about a 4" and "about an 8" are enough to choose between a thinking strategy and a calming one. If you notice you are rating everything 9 or 10, that is useful information too: it may be time for rest, support or fewer commitments, not more technique.'],
 ['Write your personal intensity ladder: what you do at 3, 6 and 9.'],
 [['At intensity 9, a sensible first move is...',['Complex reappraisal','Lower arousal or step away','Send the email','Debate'],1,'Reduce first.'],
  ['Distraction becomes a problem when...',['Used briefly','It becomes ongoing avoidance','Used at high intensity','Never'],1,'Avoidance costs.']],
 'What is on your intensity ladder at 9?',['sheppes2011-c1']),
mk(6,3,'lesson','Problem solving','Turn a stressor into a next step.',
 ['When a problem is controllable, problem solving is often the most direct regulation strategy. Across studies it was associated with fewer symptoms than rumination or avoidance (correlational).',
  'Ask first: how much of this is in my control?',
  'Problem solving often stalls on the first step because the problem is too big ("my career"). Shrink it to something you could act on this week ("I have not had a one-to-one with my lead in two months"). A plan that names who, what and when is far more likely to happen than one that names only a goal.'],
 ['Pick a current stressor.','Split it: in my control / not in my control.','Write one first step for the controllable part.'],
 [['Problem solving fits best when...',['The situation is controllable','Nothing can be done','You are at intensity 10','You want to vent'],0,'Control matters.'],
  ['First step of problem solving is...',['Blame','Define the problem in facts','Act at random','Wait forever'],1,'Clear definition.']],
 'What is in your control this week?',['aldao2010-c1']),
mk(6,4,'practice','If-then plans','Pre-commit to responses for predictable triggers.',
 ['Implementation intentions are plans in the form "If situation X, then I will do Y." A meta-analysis found them associated with better goal attainment across many domains.',
  'Emotion example: "If I feel my face heat up in a meeting, then I will take one slow breath and write down the point instead of interrupting."'],
 ['Write two if-then plans for your most common triggers.','Save them in the Journal under Plans.'],
 [['Which is a well-formed if-then plan?',['I will be calmer','If my manager criticises my work, then I will ask for one specific example','Try harder','Be good'],1,'Specific cue and action.'],
  ['If-then plans work by...',['Linking a cue to a prepared response','Removing emotions','Avoiding situations','Venting'],0,'Pre-decided response.']],
 'Which trigger most needs a plan?',['gollwitzer2006-c1']),
mk(6,5,'checkpoint','Strategy choice checkpoint','Demonstrate strategy matching.',
 ['Phase checkpoint. 80% or more marks mastery (design choice).'],['Answer from memory.'],
 [['Low-intensity irritation about a vague email; good choice?',['Leave the job','Reappraise and ask a clarifying question','Scream','Suppress forever'],1,'Low intensity suits reappraisal.'],
  ['Panic-level intensity before a call; first move?',['Lower arousal briefly','Complex analysis','Send angry text','Ruminate'],0,'Reduce arousal first.'],
  ['A strategy is adaptive when...',['It is always used','It fits the context and goals','It is popular','It removes all emotion'],1,'Flexibility.']],
 'What is your go-to strategy, and when does it not fit?',['bonanno2013-c1','sheppes2011-c1']),
// WEEK 7 Rumination and uncertainty
mk(7,1,'lesson','Rumination versus reflection','Tell unhelpful loops from useful thinking.',
 ['Repetitive thought can be constructive or not. Abstract, evaluative loops ("why am I like this?") tend to keep distress going. Concrete, process-focused thinking ("what happened step by step, and what can I do?") tends to be more useful.',
  'Rumination is associated with distress across many studies.'],
 ['Catch one loop today.','Rewrite its main "why" question as a "how" or "what next" question.'],
 [['Which is more concrete?',['Why do I always fail?','What exactly happened at 3pm and what will I try next time?','What is wrong with me?','Why me?'],1,'Concrete and process-focused.'],
  ['A sign you are ruminating is...',['New insight','No new insight or step after a while','A plan','Feeling curious'],1,'Loop without progress.']],
 'What question keeps looping for you?',['watkins2008-c1','aldao2010-c1']),
mk(7,2,'lesson','Worry windows','Contain worry in time.',
 ['Some people find it useful to postpone worries to a set 15-minute window, writing them down when they appear during the day.',
  'This is a practical containment technique. The evidence cited here concerns rumination in general rather than this specific technique, so treat it as an experiment.',
  'During the window, sort each worry: action possible, or practise letting it be.'],
 ['Choose a 15-minute window for tomorrow.','When a worry appears, write it in the Journal and postpone it.'],
 [['During a worry window you...',['Sort worries into action or let be','Worry all day','Never think','Call everyone'],0,'Sort and act.'],
  ['Evidence status of worry windows in this app is...',['Proven','Treated as an experiment','Harmful','Clinical treatment'],1,'Be honest about evidence.']],
 'What did you notice when you postponed a worry?',['watkins2008-c1']),
mk(7,3,'lesson','Tolerating uncertainty','Act well when outcomes are unknown.',
 ['Much anxiety comes from wanting certainty that is not available. Repeated checking or reassurance-seeking may calm you briefly and keep the need for certainty strong.',
  'Alternative: name the uncertainty ("I don\'t know how this will go"), decide what is good enough, and take the next step.',
  'Values help: what kind of person do you want to be while you wait?'],
 ['Pick one thing you are uncertain about.','Write: "I don\'t know X. What I can do today is Y."'],
 [['Repeated reassurance-seeking tends to...',['Solve uncertainty forever','Calm briefly while keeping the need strong','Have no effect','Always help'],1,'Short-term relief.'],
  ['A helpful uncertainty statement is...',['I must know now','I don\'t know X; today I can do Y','Everything will fail','Nothing matters'],1,'Name plus step.']],
 'Where do you seek certainty that is not available?',['kashdan2010-c1']),
mk(7,4,'practice','Handling setbacks','Recover from disappointment with a review.',
 ['After a setback: acknowledge the feeling, describe what happened in facts, find what was in your control, extract one lesson, and plan one step.',
  'Self-criticism that sounds like a verdict ("I\'m useless") rarely improves performance. A coach-like voice ("that did not work; next time try...") is more useful.',
  'Disappointment means something mattered.'],
 ['Run the five-step review on a recent setback.','Rewrite one harsh self-statement in a coach voice.'],
 [['Which is a coach voice?',['I\'m useless','That approach didn\'t work; next time I\'ll prepare the numbers first','I always fail','Never try again'],1,'Specific and forward-looking.'],
  ['Disappointment often signals...',['Nothing','That something mattered','Weakness','Danger'],1,'Value signal.']],
 'What setback taught you something useful?',['krossayduk2011-c1']),
mk(7,5,'checkpoint','Rumination and uncertainty checkpoint','Demonstrate these skills.',
 ['Phase checkpoint. 80% or more marks mastery (design choice).'],['Answer from memory.'],
 [['You keep asking "why did I say that?" for an hour. Best shift?',['Ask it louder','Switch to "what will I do next time?"','Ask friends ten times','Hide'],1,'Concrete, forward.'],
  ['Waiting for test results, a helpful move is...',['Check the portal every 5 minutes','Name uncertainty and do one valued activity','Assume the worst','Suppress'],1,'Tolerate and act.'],
  ['After a failure, a useful first step is...',['Verdict on yourself','Acknowledge feeling, then facts','Blame others','Quit'],1,'Review steps.']],
 'Which loop will you watch for this week?',['watkins2008-c1']),
// WEEK 8 Criticism
mk(8,1,'lesson','Receiving criticism','Hear feedback without defending at once.',
 ['Criticism tends to trigger a threat response: defending, attacking back or shutting down. The first goal is to understand the feedback before evaluating it.',
  'Sequence: breathe, listen to the end, ask one clarifying question, summarise what you heard, then decide later what to accept.',
  'Understanding feedback is not the same as agreeing with it.'],
 ['Write the sequence on a card.','Practise the clarifying question: "Can you give me a specific example?"'],
 [['First goal when criticised is to...',['Defend','Understand','Counterattack','Leave'],1,'Understand before evaluating.'],
  ['Summarising feedback means...',['You agree fully','You show you understood','You admit fault','You end the talk'],1,'Understanding, not agreement.']],
 'How do you usually react to criticism in the first 10 seconds?',['gross1998-c1']),
mk(8,2,'lesson','Sorting feedback','Separate accurate, partly accurate and inaccurate parts.',
 ['Most feedback mixes useful and less useful parts. Sort it: what is accurate, what is partly true, what is not true or not mine to fix.',
  'Even unfair feedback can contain information about how your work is seen.',
  'Decide what to act on after your intensity falls, not during it.'],
 ['Take a recent piece of feedback.','Sort it into three columns.','Pick one item to act on.'],
 [['Unfair feedback can still tell you...',['Nothing','How your work is perceived','That you are bad','To quit'],1,'Perception data.'],
  ['When should you decide what to act on?',['Immediately while upset','After intensity drops','Never','Only if asked twice'],1,'Decide calmer.']],
 'What feedback have you dismissed that had a useful part?',['webb2012-c1']),
mk(8,3,'lesson','Provocation and disrespect','Respond to provocation without escalating.',
 ['When someone is rude or provocative, your options include: ignore, name the behaviour calmly, set a boundary, or address it later privately.',
  'The aim is to protect your goals and dignity without matching the other person\'s tone.',
  'A calm script: "I want to keep this productive. Can we focus on X?"'],
 ['Write one calm script for a provocation you have faced.','Practise saying it at normal volume.'],
 [['A non-escalating response to a sarcastic comment is...',['Sarcasm back','"I want to keep this productive; can we focus on the deadline?"','Silence forever','Insult'],1,'Redirect calmly.'],
  ['Addressing it later privately is useful when...',['An audience makes it worse','Never','Always','Only by email'],0,'Context choice.']],
 'Which provocation gets to you most quickly?',['bonanno2013-c1']),
mk(8,4,'practice','Difficult conversations','Plan a hard conversation.',
 ['Plan: your goal for the talk, the facts, your interpretation stated as yours, the request, and how you will handle your own intensity.',
  'Use "I" statements for interpretations: "When the deadline moved without notice, I felt anxious about the client."',
  'Expect discomfort; plan for it rather than waiting until it disappears.'],
 ['Plan one upcoming conversation using the five parts.','Write your opening line.'],
 [['A good opening states...',['Accusations','Facts and your experience, then a request','Everything wrong','Nothing'],1,'Facts, I-statement, request.'],
  ['Waiting for discomfort to vanish before a talk usually...',['Helps','Delays indefinitely','Is required','Is efficient'],1,'Plan for discomfort.']],
 'What conversation have you been postponing?',['gollwitzer2006-c1']),
mk(8,5,'review','Week 8 review','Retrieve criticism skills.',
 ['Review. Items you miss return later.'],['Answer from memory.'],
 [['Which sequence fits receiving criticism?',['Defend, attack, leave','Breathe, listen, clarify, summarise','Agree with everything','Change the topic'],1,'Understand first.'],
  ['Which response sets a boundary?',['"Please don\'t speak to me like that; let\'s continue when it\'s respectful."','Shouting','Crying silently','Agreeing'],0,'Clear and calm.']],
 'Which criticism skill will you use this week?',['gross1998-c1']),
// WEEK 9 Conflict and boundaries
mk(9,1,'lesson','Boundaries','State limits clearly and kindly.',
 ['A boundary describes what you will do, not what the other person must feel. "I can\'t take that on this week; I can look at it Monday."',
  'Boundaries often bring discomfort, such as guilt or fear of disapproval.',
  'Keep it short, specific and repeatable.'],
 ['Write one boundary you need.','Make it under 20 words.'],
 [['A boundary statement focuses on...',['What you will do','Controlling others\' feelings','Long apologies','Threats'],0,'Your action.'],
  ['Guilt after setting a boundary means...',['It was wrong','It is a common feeling, not proof','You must retract','Nothing'],1,'Feeling is not verdict.']],
 'Where do you need a boundary most?',['kashdan2010-c1']),
mk(9,2,'lesson','Repair after conflict','Repair relationships after a rupture.',
 ['Conflicts happen. Repair matters: acknowledge your part specifically, avoid "but", and state what you will do differently.',
  'A repair is not admitting total fault; it is taking responsibility for your share.',
  'Timing: when both people are calmer.'],
 ['Think of an unrepaired conflict.','Write a two-sentence repair.'],
 [['A good repair includes...',['"Sorry, but you..."','Specific acknowledgement and a change','Silence','Blame'],1,'Specific ownership.'],
  ['Repair works best when...',['Both are calmer','During the peak','Never','By group chat'],0,'Timing.']],
 'What repair is overdue?',['gross1998-c1']),
mk(9,3,'lesson','Validation','Acknowledge others\' emotions to lower heat.',
 ['Validation means showing you understand why someone feels as they do, without necessarily agreeing with their view or demands.',
  '"I can see this deadline change put you in a tough spot" can lower intensity on both sides.',
  'Validation and problem solving are separate steps; validate first.'],
 ['Write a validating sentence for a recent tense exchange.'],
 [['Validation means...',['Agreeing with everything','Showing understanding of the feeling','Fixing it now','Ignoring'],1,'Understanding.'],
  ['Order of steps?',['Solve then validate','Validate then solve','Neither','Both at once loudly'],1,'Validate first.']],
 'Who would benefit from validation from you?',['gross1998-c1']),
mk(9,4,'practice','Conflict drills','Practise conflict responses.',
 ['Run three Scenario Gym items in the Boundaries and Provocation categories.',
  'Focus on the emotion step before choosing a response.'],
 ['Complete three gym scenarios.','Note one response you would now choose differently.'],
 [['In the gym, before choosing a response you should...',['Skip the emotion step','Name likely emotions','Pick randomly','Pick the harshest'],1,'Name first.'],
  ['Feedback on scenarios is meant to...',['Shame you','Explain trade-offs','Rank you publicly','Nothing'],1,'Learning.']],
 'Which scenario was hardest?',['bonanno2013-c1']),
mk(9,5,'checkpoint','Criticism and conflict checkpoint','Demonstrate weeks 8-9 skills.',
 ['Phase checkpoint. 80% or more marks mastery (design choice).'],['Answer from memory.'],
 [['A colleague snaps at you in front of others. A good option?',['Snap back','Calmly redirect, then talk privately later','Cry and leave','Report on social media'],1,'Protect goals.'],
  ['Feedback you think is unfair: first step?',['Dismiss it','Ask for an example and understand it','Argue','Quit'],1,'Understand.'],
  ['"I can\'t take that on, but I can help Monday" is...',['A boundary','Aggression','Avoidance','Suppression'],0,'Clear limit plus option.']],
 'What did you learn about yourself in conflict?',['bonanno2013-c1']),
// WEEK 10 Professional composure I
mk(10,1,'lesson','Composure is not coldness','Stay effective while feeling.',
 ['Professional composure means staying able to think, listen and decide while emotions are present. It does not mean showing nothing.',
  'Brief, deliberate expression ("I\'m concerned about this timeline") is often more effective than hidden tension that leaks later.',
  'Suppression as a habit carries costs; choose when to hold back and when to name.'],
 ['Write one way you can name concern professionally.'],
 [['Composure means...',['No feelings','Thinking clearly while feeling','Shouting','Leaving'],1,'Effectiveness.'],
  ['"I\'m concerned about this timeline" is...',['Unprofessional','Brief deliberate expression','Suppression','Venting'],1,'Measured naming.']],
 'Where do you leak hidden tension at work?',['grossjohn2003-c1']),
mk(10,2,'lesson','Unreasonable demands','Respond to excessive asks.',
 ['When a demand seems unreasonable, separate: what exactly is asked, the deadline, what is possible, and what trade-offs exist.',
  'Respond with options: "I can do A by Friday or B by Wednesday; which matters more?"',
  'This shifts from emotional reaction to shared problem solving.'],
 ['Take a recent demand.','Write an options response.'],
 [['An options response...',['Refuses everything','Offers trade-offs','Agrees silently','Complains'],1,'Trade-offs.'],
  ['First step with a demand is...',['Clarify what exactly is asked','Panic','Refuse','Agree'],0,'Clarify.']],
 'Which demand did you accept that you should have negotiated?',['aldao2010-c1']),
mk(10,3,'lesson','Decisions under pressure','Decide well when time is short.',
 ['Under pressure, slow down the first 30 seconds: breathe, state the decision, state the deadline, list two options.',
  'Good enough decisions with a review point often beat perfect decisions made too late.',
  'Name what you will check afterwards.'],
 ['Write a 30-second pressure routine.'],
 [['The first move in a pressure decision is...',['Act instantly','Pause briefly and define the decision','Wait a week','Ask everyone'],1,'Brief pause.'],
  ['A review point helps by...',['Allowing course correction','Adding blame','Delaying','Nothing'],0,'Learning loop.']],
 'What is your pressure routine?',['gollwitzer2006-c1']),
mk(10,4,'practice','Pressure drills','Practise pressure scenarios.',
 ['Complete three Pressure scenarios in the gym.','Use your 30-second routine before each choice.','Compare with feedback.'],
 ['Complete three pressure scenarios.'],
 [['Before choosing in a pressure scenario...',['Use the routine','Skip','Pick fastest','Pick longest'],0,'Routine.'],
  ['Good enough plus review is...',['Lazy','Often effective under time limits','Wrong','Banned'],1,'Pragmatic.']],
 'Which pressure scenario felt real?',['bonanno2013-c1']),
mk(10,5,'review','Week 10 review','Retrieve composure skills.',
 ['Review. Missed items return.'],['Answer from memory.'],
 [['A demand to finish two projects by tomorrow; good reply?',['"Fine" then fail','"I can finish one by tomorrow; which first?"','Ignore','Quit'],1,'Options.'],
  ['Composure includes...',['Measured naming of concern','Never speaking','Shouting','Sarcasm'],0,'Measured expression.']],
 'What did you practise this week?',['grossjohn2003-c1']),
// WEEK 11 Professional composure II
mk(11,1,'lesson','Uncertain outcomes at work','Stay effective during reorganisations and waiting.',
 ['When outcomes are unknown, focus on what you control: quality of work, relationships, information gathering, and preparation for options.',
  'Limit information-checking to set times to avoid rumination.',
  'Name the uncertainty with colleagues without spreading catastrophes.'],
 ['List three controllables in a current uncertainty.'],
 [['During a reorganisation, a useful focus is...',['Rumour checking hourly','What you control','Assuming the worst','Withdrawing'],1,'Controllables.'],
  ['Checking news at set times helps...',['Contain rumination','Increase worry','Nothing','Avoid all info'],0,'Containment.']],
 'What can you control this month?',['watkins2008-c1']),
mk(11,2,'lesson','Recovery after a hard meeting','Reset after difficult interactions.',
 ['After a difficult meeting: reset the body (walk, breathe), note facts and actions while fresh, then switch attention deliberately to the next task.',
  'Avoid replaying the meeting abstractly; if you review, do it concretely with a next step.',
  'Self-distanced reflection can help process it.'],
 ['Write a three-step recovery routine.'],
 [['Right after a hard meeting, a good first step is...',['Replay it all evening','Reset body and note actions','Send angry email','Ignore actions'],1,'Reset then note.'],
  ['Reviewing a meeting is useful when...',['Concrete with next step','Abstract and evaluative','Hourly','Never'],0,'Concrete.']],
 'What is your recovery routine?',['krossayduk2011-c1','watkins2008-c1']),
mk(11,3,'lesson','Disagreeing with seniors','Disagree respectfully upward.',
 ['Disagreeing with someone senior can trigger fear. Prepare: shared goal, specific concern, evidence, proposal.',
  '"I share the goal of X. I\'m concerned Y because Z. Could we try W?"',
  'Accept that they may still decide differently.'],
 ['Write a disagreement script for a current issue.'],
 [['A respectful disagreement begins with...',['Shared goal','Criticism','Threat','Silence'],0,'Common ground.'],
  ['If they still decide differently...',['Accept and note concerns','Sabotage','Rage','Gossip'],0,'Professional acceptance.']],
 'What disagreement are you holding back?',['bonanno2013-c1']),
mk(11,4,'practice','Professional drills','Mixed professional scenarios.',
 ['Complete three professional-context gym scenarios across categories.','Apply fact versus interpretation first.'],
 ['Complete three professional scenarios.'],
 [['In each scenario, start with...',['Fact versus interpretation','The harshest reply','Silence','Guessing'],0,'Separate first.'],
  ['Professional context means...',['No feelings allowed','Feelings plus role obligations','Only facts','Only feelings'],1,'Your feelings still count; role obligations shape which responses fit.']],
 'Which professional skill is strongest now?',['gross1998-c1']),
mk(11,5,'checkpoint','Professional composure checkpoint','Demonstrate weeks 10-11.',
 ['Phase checkpoint. 80% or more marks mastery (design choice).'],['Answer from memory.'],
 [['Your manager questions your figures in front of the team. A good response?',['"Good question. I\'ll check and confirm by 3pm."','"You\'re wrong."','Silence and sulk','Leave'],0,'Composed, action-focused.'],
  ['Unknown outcome of a promotion; useful move?',['Check status hourly','Focus on controllables','Assume rejection','Quit'],1,'Controllables.'],
  ['After a tense call, you should...',['Reset, note actions, switch focus','Replay all night','Email everyone','Skip lunch'],0,'Recovery.']],
 'What does composure look like for you now?',['bonanno2013-c1']),
// WEEK 12 Patterns and maintenance
mk(12,1,'lesson','Mapping your patterns','Find recurring triggers and responses.',
 ['Look at your journal: which situations recur, which interpretations, which urges, which outcomes? The Progress page shows your most frequent emotions and triggers.',
  'Describe patterns, not causes. "I tend to get defensive when feedback is public" is a pattern. "Because of my childhood" is a causal claim this data cannot support.',
  'Patterns point to where if-then plans help most.'],
 ['Open Progress and review your top triggers.','Write one pattern statement.'],
 [['Which is a pattern statement?',['I get defensive when feedback is public','It is because of my parents','I am broken','Everyone is unfair'],0,'Describes, not explains.'],
  ['Your journal data can support...',['Causal claims about childhood','Descriptive patterns','Diagnoses','Nothing'],1,'Descriptive only.']],
 'What pattern stands out?',['bonanno2013-c1']),
mk(12,2,'lesson','When to seek more support','Recognise limits of self-training.',
 ['This app is training, not therapy or crisis support. If emotions are persistently overwhelming, if you feel unsafe, or if daily functioning is affected, talking to a qualified professional is a sensible step.',
  SUPPORT_LESSON_TEXT],
 ['Note one person and one professional option you could contact.'],
 [['This app is...',['Therapy','Skills training, not treatment','Crisis support','Diagnosis'],1,'Training only.'],
  ['If you feel unsafe, you should...',['Keep using the app only','Contact emergency services or a professional','Wait','Ignore'],1,'Get help.']],
 'Who is in your support network?',['hayes2006-c1']),
mk(12,3,'lesson','Maintenance plan','Build a sustainable practice.',
 ['Skills fade without use. Spaced reviews in this app bring back items at 2, 7 and 21 days after mastery.',
  'Keep if-then plans for your top three triggers.',
  'Notice which skills you actually use. After a few weeks, most people rely on two or three. That is fine. Use the gym to keep one less familiar skill in reach, so you are not left with only one tool when a new kind of situation arrives.'],
 ['Write your maintenance plan in the Journal.'],
 [['Why spaced reviews?',['They improve long-term retention','They are fun only','No reason','To add notifications'],0,'Spacing.'],
  ['A light maintenance plan includes...',['Daily hour-long sessions','A few short practices weekly','Nothing','Only reading'],1,'Sustainable.']],
 'What maintenance will you keep?',['cepeda2006-c1']),
mk(12,4,'practice','Integration drill','Use the full chain on a real event.',
 ['Take a real recent event and run the full chain: facts, interpretations, emotions with intensity, urge, strategy chosen, outcome, lesson.',
  'Then write one if-then plan for next time.'],
 ['Complete a full Journal reflection with all fields.'],
 [['The full chain ends with...',['A lesson and plan','Blame','Nothing','Venting'],0,'Learning loop.'],
  ['Strategy choice should consider...',['Context and intensity','Only habit','Mood of others only','Nothing'],0,'Flexibility.']],
 'What did the full chain reveal?',['bonanno2013-c1']),
mk(12,5,'checkpoint','Final checkpoint','Demonstrate integration.',
 ['Final checkpoint. Then take the post-programme assessment from Progress. 80% threshold is a design choice.'],['Answer from memory.'],
 [['Which best summarises this programme\'s aim?',['Never feel bad','Flexible, context-sensitive regulation','Always reappraise','Hide emotions'],1,'Core aim.'],
  ['A pattern you notice in your journal is best described...',['As a cause','As a descriptive pattern','As a diagnosis','As a fact about character'],1,'Descriptive.'],
  ['Skills are retained best with...',['One cram session','Spaced retrieval','Never reviewing','Reading once'],1,'Spacing and retrieval.']],
 'What will you carry forward?',['cepeda2006-c1','bonanno2013-c1']),
];
/** Claims added in the compliance pass (spec 4.1): digital-delivery evidence and the 2015 process-model update. */
const ADD_CLAIMS: Record<string, string[]> = { w01d1: ['eisenstadt2021-c1', 'macrynikola2024-c1'], w01d3: ['gross2015-c1'] };
export const SESSIONS: Session[] = RAW.map(s => ADD_CLAIMS[s.id] ? { ...s, claimIds: [...s.claimIds, ...ADD_CLAIMS[s.id]] } : s)
  .map(s => ({ ...s, checks: s.checks.map(withDistractors), altChecks: s.altChecks.map(withDistractors) }));
